/**
 * @fileoverview Enquiry API service — all HTTP calls for /api/enquiries.
 * Returns raw response data; error handling done in hooks.
 */

import axiosInstance from "./axiosInstance";

/**
 * Fetch paginated enquiry list.
 * @param {object} params - { page, limit, search, status, department, sortBy, sortOrder }
 * @returns {Promise<{ data: object[], pagination: object }>}
 */
export const fetchEnquiries = async (params = {}) => {
  const res = await axiosInstance.get("/enquiries", { params });
  return res.data;
};

/**
 * Fetch single enquiry by ID.
 * @param {string} id - MongoDB ObjectId
 * @returns {Promise<{ data: object }>}
 */
export const fetchEnquiry = async (id) => {
  const res = await axiosInstance.get(`/enquiries/${id}`);
  return res.data;
};

/**
 * Create new admission enquiry.
 * @param {object} body - { name, email, phone, course, department, status?, notes? }
 * @returns {Promise<{ data: object }>}
 */
export const createEnquiry = async (body) => {
  const res = await axiosInstance.post("/enquiries", body);
  return res.data;
};

/**
 * Partially update an enquiry.
 * @param {string} id - MongoDB ObjectId
 * @param {object} body - Partial enquiry fields
 * @returns {Promise<{ data: object }>}
 */
export const updateEnquiry = async (id, body) => {
  const res = await axiosInstance.patch(`/enquiries/${id}`, body);
  return res.data;
};

/**
 * Atomic status update.
 * @param {string} id - MongoDB ObjectId
 * @param {string} status - "Pending" | "Contacted" | "Admitted" | "Rejected"
 * @returns {Promise<{ data: object }>}
 */
export const updateEnquiryStatus = async (id, status) => {
  const res = await axiosInstance.patch(`/enquiries/${id}/status`, { status });
  return res.data;
};

/**
 * Delete single enquiry.
 * @param {string} id - MongoDB ObjectId
 * @returns {Promise<{ message: string }>}
 */
export const deleteEnquiry = async (id) => {
  const res = await axiosInstance.delete(`/enquiries/${id}`);
  return res.data;
};

/**
 * Bulk delete enquiries.
 * @param {string[]} ids - Array of MongoDB ObjectIds
 * @returns {Promise<{ message: string }>}
 */
export const bulkDeleteEnquiries = async (ids) => {
  const res = await axiosInstance.delete("/enquiries/bulk", { data: { ids } });
  return res.data;
};

/**
 * Fetch KPI stats: total, by-status counts, top departments.
 * @returns {Promise<{ data: object }>}
 */
export const fetchStats = async () => {
  const res = await axiosInstance.get("/enquiries/stats");
  return res.data;
};
